// Regenerate the script fallback used only when index.html is opened via file://.
const fs=require('node:fs');const path=require('node:path');
const root=path.join(__dirname,'..');
const config=JSON.parse(fs.readFileSync(path.join(root,'static/configs/default.json'),'utf8'));
fs.writeFileSync(path.join(root,'static/configs/file_default.js'),
  '// Generated by node scripts/update_file_config.cjs from default.json.\n'+
  'globalThis.PACMAN_FILE_CONFIG = '+JSON.stringify(config,null,2)+';\n');
